export type Job<T> = () => Promise<T>;

export class JobQueue {
  private readonly concurrency: number;
  private readonly maxRetries: number;
  private readonly pending: Array<() => Promise<void>> = [];
  private idleWaiters: Array<() => void> = [];
  private running = 0;

  constructor(concurrency: number, maxRetries = 3) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new RangeError("concurrency must be a positive integer");
    }
    if (!Number.isInteger(maxRetries) || maxRetries < 0) {
      throw new RangeError("maxRetries must be a non-negative integer");
    }
    this.concurrency = concurrency;
    this.maxRetries = maxRetries;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: Job<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.runWithRetries(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves when nothing is running or waiting. Failed jobs do not reject it. */
  onIdle(): Promise<void> {
    if (this.isIdle()) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  get size(): number {
    return this.pending.length + this.running;
  }

  private isIdle(): boolean {
    return this.running === 0 && this.pending.length === 0;
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const start = this.pending.shift()!;
      this.running++;
      void start().finally(() => {
        this.running--;
        this.next();
      });
    }
    if (this.isIdle() && this.idleWaiters.length > 0) {
      const waiters = this.idleWaiters;
      this.idleWaiters = [];
      for (const resolve of waiters) resolve();
    }
  }

  // A retrying job keeps its concurrency slot until it succeeds or gives up.
  private async runWithRetries<T>(job: Job<T>): Promise<T> {
    for (let attempt = 0; ; attempt++) {
      try {
        return await job();
      } catch (err) {
        if (attempt >= this.maxRetries) throw err;
      }
    }
  }
}

